import{_ as t,c as a,o,ag as r}from"./chunks/framework.CQuhCYrb.js";const d=JSON.parse('{"title":"Sock Puppet Accounts/Phase 2: Make Them Money","description":"","frontmatter":{"title":"Sock Puppet Accounts/Phase 2: Make Them Money"},"headers":[],"relativePath":"general/sock-puppet-accounts-phase-2-make-them-money.md","filePath":"general/sock-puppet-accounts-phase-2-make-them-money.md","lastUpdated":null}'),s={name:"general/sock-puppet-accounts-phase-2-make-them-money.md"};function n(i,e,l,c,p,u){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="sock-puppet-accounts-phase-2-make-them-money" tabindex="-1">Sock Puppet Accounts/Phase 2: Make Them Money <a class="header-anchor" href="#sock-puppet-accounts-phase-2-make-them-money" aria-label="Permalink to &quot;Sock Puppet Accounts/Phase 2: Make Them Money&quot;">​</a></h1><h2 id="phase-2-make-them-money" tabindex="-1">Phase 2: Make Them Money <a class="header-anchor" href="#phase-2-make-them-money" aria-label="Permalink to &quot;Phase 2: Make Them Money&quot;">​</a></h2><p>In this phase, the goal is to make your sock puppet account valuable to platforms by engaging with ads, making small purchases, and allowing platforms to collect data on your activity. This helps reduce the likelihood of your account being flagged or removed by making it appear as a profitable user for the platform.</p><h3 id="principle" tabindex="-1">Principle <a class="header-anchor" href="#principle" aria-label="Permalink to &quot;Principle&quot;">​</a></h3><p><strong>Working Theory</strong>: Platforms are less likely to shut down an account that makes them money. The goal is to build a history of ad engagement data to make the account valuable to the platform. By interacting with ads, purchasing low-cost products, and enabling data-tracking features, you can increase the account&#39;s legitimacy and decrease the likelihood of it being flagged for removal.</p><p>The strategy focuses on leveraging “low-hanging fruit,” such as basic eCommerce interactions, ad clicks, and social media engagement, which help the platform profile you as a valuable user.</p><p>Key actions include enabling all features that allow companies to personalize ads, track your activity, and market directly to you. In short, you want to position your sock puppet account as a “money maker” for the platform, so they’ll be more inclined to keep it active.</p><p>Return to <a href="/general/sock-puppet-accounts-creation.html">Puppet Creation Outline</a>.</p><h3 id="actions" tabindex="-1">Actions <a class="header-anchor" href="#actions" aria-label="Permalink to &quot;Actions&quot;">​</a></h3><p>To build credibility and sustain your sock puppet account, engage in the following actions that are consistent with the story or persona you’ve created for your sock account:</p><p><strong>eCommerce</strong>: Engage with eCommerce platforms such as Amazon, eBay, or any other large retailer. Even small purchases or browsing history can contribute to building an ad profile for your account.</p><ul><li><p>Search for and purchase small, inexpensive items.</p></li><li><p>Follow promotional links from newsletters or social media platforms.</p></li></ul><p><strong>Newsletters</strong>: Sign up for newsletters from websites or companies that align with the interests of your sock account’s persona. Engage with the emails, click on links, and interact with promoted content.</p><ul><li>Subscribe to newsletters from major retailers, tech blogs, or lifestyle companies.</li></ul><p><strong>Blogs and Forums</strong>: Participate in niche blogs and forums that match your sock’s interests. Comment on posts and contribute to discussions. This will build a digital footprint that aligns with your sock&#39;s persona.</p><ul><li>Blog comments and engagement in forums add to credibility and ad relevance.</li></ul><p><strong>Social Media Platforms</strong>:</p><ul><li><p><strong>Twitter</strong>: Follow brands, influencers, and news outlets. Retweet, like, and comment on ads and promotional posts.</p></li><li><p><strong>Instagram</strong>: Follow brand pages, engage with ads, and like or comment on promotional posts.</p></li><li><p><strong>Reddit</strong>: Join subreddits related to your sock puppet’s persona. Engage with Reddit ads, upvote posts, and interact with comments.</p></li></ul><p><strong>Content Engagement</strong>: Like, post, and repost content that aligns with your sock puppet’s story. Sharing popular posts related to shopping, lifestyle, or consumer products will increase the account&#39;s value for advertisers.</p><h3 id="best-practices" tabindex="-1">Best Practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best Practices&quot;">​</a></h3><ul><li><p><strong>Consistency</strong>: Keep your actions consistent with the persona and story of your sock puppet account. If your sock is portrayed as a tech enthusiast, engage with tech-related products and ads. If the sock persona is a lifestyle blogger, engage with fashion, health, and beauty products.</p></li><li><p><strong>Ad Interaction</strong>: Regularly click on ads and interact with promoted content. Browsing through ad-recommended products creates a browsing history that platforms use to fine-tune your ad profile.</p></li><li><p><strong>Trackable Data</strong>: Allow companies and platforms to track your activity to personalize ads. Enable cookies and tracking features on your sock puppet’s browser or account to make sure your actions are recorded and contribute to the account&#39;s value.</p></li></ul><h3 id="tools" tabindex="-1">Tools <a class="header-anchor" href="#tools" aria-label="Permalink to &quot;Tools&quot;">​</a></h3><ul><li><strong>Ad Optimization</strong>: Use tools or browser extensions that help optimize ad tracking and ensure companies can capture as much data as possible. Be careful not to use ad blockers, as they can undermine the purpose of this phase.</li></ul><h3 id="resources" tabindex="-1">Resources <a class="header-anchor" href="#resources" aria-label="Permalink to &quot;Resources&quot;">​</a></h3><ul><li><a href="https://www.thepaperboy.com/" target="_blank" rel="noreferrer">Paperboy Online Newspapers | US &amp; World Newspapers</a> – A great resource to find various news outlets to engage with, based on your sock puppet’s interests.</li></ul><p><strong>Additional Resources for eCommerce and Content Engagement</strong>:</p><ul><li><p><a href="http://www.amazon.com" target="_blank" rel="noreferrer">Amazon</a></p></li><li><p><a href="http://www.ebay.com" target="_blank" rel="noreferrer">eBay</a></p></li><li><p><a href="http://www.etsy.com" target="_blank" rel="noreferrer">Etsy</a></p></li><li><p><a href="http://www.buzzfeed.com" target="_blank" rel="noreferrer">BuzzFeed</a></p></li></ul><h3 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h3><p>[Footprint] [Security] [Media] [Management] [Monetization] [Tracking] [Required]</p>',29)])])}const m=t(s,[["render",n]]);export{d as __pageData,m as default};
